import { rootLogger } from '@shared/context/observability/logger.service';
import { signal, Signal } from '@angular/core';
import { catchError, EMPTY, finalize, Observable, Subscription, tap } from 'rxjs';

export interface SelectorProvider<T, R> extends Signal<T[] | undefined> {
  searching: Signal<boolean>;
  error: Signal<unknown>;
  selection: Signal<T | null>;
  // Convierte una lista de datos remotos { uid: '12', nombre: '22', email: 'fake@mail.net' } en un { '$ref': 22 }
  search(text: string | null): void;

  // Convierte el dato bueno { '$ref': 22 } en un dato para plantilla { uid: '12', nombre: '22', email: 'fake@mail.net' } que usara
  select(value: R | null): void;

  // Convierte el dato remotoo en un string
  display(item: T): string;

  // Convierte el dato remoto object { uid: '12', nombre: '22', email: 'fake@mail.net' } en un { '$ref': 22 }
  value(item: T): R;

  equals(one: R, other: R): boolean;
}

export interface SelectorProviderHandler<T, R> {
  search(text: string): Observable<T[]>;

  // Convierte el dato bueno { '$ref': 22 } en un dato para plantilla { uid: '12', nombre: '22', email: 'fake@mail.net' } que usara
  select(value: R): Observable<T | undefined>;

  equals(one: R, other: R): boolean;

  // Convierte el dato remotoo en un string
  display(item: T): string;

  // Convierte el dato remoto object { uid: '12', nombre: '22', email: 'fake@mail.net' } en un { '$ref': 22 }
  value(item: T): R;
}

export function selectorProvider<T, R>(handler: SelectorProviderHandler<T, R>): SelectorProvider<T, R> {
  const searching = signal(false);
  const errors = signal<unknown>(null);
  const selection = signal<T | null>(null);
  const val = signal<T[] | undefined>(undefined);
  const result = val as any;
  let subs: Subscription;
  // Cada petición lleva su número: los avisos diferidos de una petición ya sustituida no tocan `searching`
  let current = 0;
  const begin = () => {
    subs?.unsubscribe();
    const id = ++current;
    setTimeout(() => id === current && searching.set(true));
    return id;
  };
  const end = (id: number) => setTimeout(() => id === current && searching.set(false));
  result.search = (text: string) => {
    const id = begin();
    errors.set(null);
    subs = handler
      .search(text)
      .pipe(
        catchError((error) => {
          rootLogger.error('Selector search failed', error);
          errors.set(error);
          return EMPTY;
        }),
        // Los repositorios devuelven observables vivos que no completan: la carga acaba con el primer dato
        tap(() => end(id)),
        finalize(() => end(id)),
      )
      .subscribe((values) => {
        val.set(values);
      });
  };
  result.select = (value: R | null) => {
    if (value !== null && value !== undefined) {
      const id = begin();
      errors.set(null);
      subs = handler
        .select(value)
        .pipe(
          catchError((error) => {
            rootLogger.error('Selector selection failed', error);
            errors.set(error);
            return EMPTY;
          }),
          // Los repositorios devuelven observables vivos que no completan: la carga acaba con el primer dato
          tap(() => end(id)),
          finalize(() => end(id)),
        )
        .subscribe((response) => {
          const prev = val();
          if (response && prev) {
            const key = handler.value(response);
            val.set(prev.some((into) => handler.equals(key, handler.value(into))) ? prev : [response, ...prev]);
          } else {
            val.set(response ? [response] : undefined);
          }
          selection.set(response || null);
        });
    } else {
      subs?.unsubscribe();
      current++;
      val.set(undefined);
      selection.set(null);
      errors.set(null);
      searching.set(false);
    }
  };
  result.error = errors.asReadonly();
  result.selection = selection;
  result.searching = searching;
  result.equals = handler.equals;
  result.display = handler.display;
  result.value = handler.value;
  return result;
}
